import sys
sys.setrecursionlimit(20000)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(nodes, index):
    if index >= len(nodes) or nodes[index] is None:
        return None
    root = TreeNode(nodes[index])
    root.left = build_tree(nodes, 2 * index + 1)
    root.right = build_tree(nodes, 2 * index + 2)
    return root

def dfs(node):
    if not node:
        return 0, 0

    left_moves, left_balance = dfs(node.left)
    right_moves, right_balance = dfs(node.right)

    current_balance = node.val - 1 + left_balance + right_balance
    total_moves = left_moves + right_moves + abs(left_balance) + abs(right_balance)

    return total_moves, current_balance

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        nodes = list(map(int, line.split()))
        root = build_tree(nodes, 0)
        moves, _ = dfs(root)
        print(moves)
    except Exception:
        pass

if __name__ == "__main__":
    main()
